CREATE VIEW dept_summary AS
SELECT d.dname, COUNT(e.empno) total,
       SUM(e.sal) total_sal
FROM dept d JOIN emp e
ON d.deptno = e.deptno
GROUP BY d.dname;

SELECT * FROM dept_summary
ORDER BY dname;

UPDATE dept_summary SET total = 10
WHERE dname = 'SALES';

